package com.elitedarkkaiser.nubialy;
import android.os.*;
import android.graphics.ImageDecoder;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.card.MaterialCardView;
import java.util.*;
import java.util.concurrent.*;
/** App-only source previews and explicit next-boot staging. Never mounts or reboots from the app. */
public final class BootAnimationActivity extends AppCompatActivity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final List<MaterialCardView> choices=new ArrayList<>();private String selected="rising";private ImageView preview;private TextView status,description;private MaterialButton apply,check,restore,play;private AnimatedImageDrawable animation;private long ticket;private boolean stopped=true,closed,busy,ready;
 @Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(20),dp(16),dp(20),dp(24));scroll.addView(content);setContentView(scroll);androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(scroll,(v,insets)->{var bars=insets.getInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});content.addView(PersonalizationUi.toolbar(this,"Boot animations"));if(!CompatibilityPolicy.isSupportedDevice(android.os.Build.MODEL,android.os.Build.DEVICE)||!CompatibilityPolicy.isSupportedSdk(android.os.Build.VERSION.SDK_INT)){content.addView(text("NX809J / NX789J on Android 15 or 16 only.",18));return;}
  selected=getSharedPreferences("boot_animation_draft",0).getString("selection","rising");if(BootAnimations.find(selected)==null)selected="rising";
  LinearLayout sample=panel(content,"Animation preview");preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);preview.setBackgroundColor(android.graphics.Color.BLACK);sample.addView(preview,new LinearLayout.LayoutParams(-1,dp(300)));description=text("Source-frame preview. Playback keeps the archive’s original proportions.",14);sample.addView(description);play=button("Play preview");sample.addView(play);play.setOnClickListener(v->loadPreview(true));
  LinearLayout styles=panel(content,"Choose your animation");boolean stacked=getResources().getConfiguration().fontScale>1.3f||getResources().getConfiguration().screenWidthDp<360;LinearLayout row=null;
  for(int i=0;i<BootAnimations.ENTRIES.length;i++){var entry=BootAnimations.ENTRIES[i];if(stacked||i%2==0){row=new LinearLayout(this);styles.addView(row);}MaterialCardView card=new MaterialCardView(this);PersonalizationUi.panel(card);card.setCardBackgroundColor(getColor(R.color.surface_container_high));card.setRadius(dp(24));card.setClickable(true);card.setFocusable(true);card.setTag("boot-animation:"+entry.id());card.setOnClickListener(v->choose(entry.id()));choices.add(card);LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setGravity(Gravity.CENTER);body.setPadding(dp(12),dp(12),dp(12),dp(12));body.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);ImageView thumb=new ImageView(this);thumb.setScaleType(ImageView.ScaleType.FIT_CENTER);try(var input=getAssets().open("bootanimations/"+entry.id()+"-thumb.webp")){thumb.setImageDrawable(Drawable.createFromStream(input,null));}catch(Exception unavailable){}body.addView(thumb,new LinearLayout.LayoutParams(-1,dp(140)));TextView name=text(entry.name(),17);name.setGravity(Gravity.CENTER);body.addView(name);card.addView(body);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(stacked?-1:0,-2,stacked?0:1);params.setMargins(dp(4),dp(4),dp(4),dp(4));row.addView(card,params);}
  LinearLayout actions=panel(content,"Apply on next boot");actions.addView(text("Systemless only. The guard exposes one animation file at boot; the original stays untouched. Selecting a card only saves a draft. Root and the updated guard are required.",14));status=text("Checking recovery module…",14);actions.addView(status);apply=button("Apply on next boot");apply.setTag("boot-apply");apply.setEnabled(false);actions.addView(apply);apply.setOnClickListener(v->run("stage_"+selected));check=button("Check module & selection");actions.addView(check);check.setOnClickListener(v->run("status"));restore=button("Restore stock on next boot");actions.addView(restore);restore.setOnClickListener(v->run("restore"));actions.addView(text("Reboot after applying or restoring. The guard disarms the animation for the next boot if the previous boot did not complete. Its Action also stops it. A bind already active lasts until reboot. This cannot guarantee recovery from every boot failure.",14));mark();
 }
 private void choose(String id){if(busy||BootAnimations.find(id)==null)return;selected=id;mark();loadPreview(false);worker.execute(()->getSharedPreferences("boot_animation_draft",0).edit().putString("selection",id).commit());}
 private void mark(){for(int i=0;i<choices.size();i++){var e=BootAnimations.ENTRIES[i];var c=choices.get(i);boolean chosen=e.id().equals(selected);c.setSelected(chosen);c.setStrokeWidth(dp(chosen?3:0));c.setStrokeColor(getColor(R.color.primary));c.setContentDescription(e.name()+(chosen?", selected":""));}}
 private void loadPreview(boolean animated){if(preview==null)return;stopAnimation();long current=++ticket;String id=selected;var e=BootAnimations.find(id);description.setText(e.name()+" · "+e.width()+" × "+e.height()+"\nSource-frame preview"+(e.dynamicColors()?"; dynamic playback colors may differ.":"; original archive proportions."));worker.execute(()->{Drawable drawable=null;try{drawable=ImageDecoder.decodeDrawable(ImageDecoder.createSource(getAssets(),"bootanimations/"+id+(animated?".webp":"-thumb.webp")));}catch(Exception unavailable){}Drawable result=drawable;runOnUiThread(()->{if(closed||stopped||ticket!=current){if(result instanceof AnimatedImageDrawable a)a.stop();return;}preview.setImageDrawable(result);if(animated&&result instanceof AnimatedImageDrawable a){animation=a;a.setRepeatCount(0);a.start();}});});}
 private void run(String operation){if(busy||apply==null)return;busy=true;controls();status.setText(operation.equals("status")?"Checking recovery module…":"Working…");worker.execute(()->{String result=BootAnimationCommand.run(getApplicationContext(),operation);String reply=operation.equals("status")?result:BootAnimationCommand.run(getApplicationContext(),"status");BootAnimationState state=BootAnimationState.parse(reply);runOnUiThread(()->{if(closed||isFinishing()||isDestroyed())return;busy=false;ready=state!=null&&state.ready();status.setText(state==null?result:state.summary()+(operation.equals("status")?"":"\n"+result));controls();});});}
 private void controls(){apply.setEnabled(!busy&&ready);check.setEnabled(!busy);restore.setEnabled(!busy);play.setEnabled(!busy);for(View card:choices)card.setEnabled(!busy);}
 private void stopAnimation(){if(animation!=null){animation.stop();animation=null;}}
 @Override protected void onStart(){super.onStart();stopped=false;if(preview!=null){loadPreview(false);run("status");}}
 @Override protected void onStop(){stopped=true;ticket++;stopAnimation();if(preview!=null)preview.setImageDrawable(null);super.onStop();}
 @Override protected void onDestroy(){closed=true;ticket++;stopAnimation();worker.shutdown();super.onDestroy();}
 private LinearLayout panel(LinearLayout parent,String title){MaterialCardView card=new MaterialCardView(this);PersonalizationUi.panel(card);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.setMargins(0,dp(14),0,0);parent.addView(card,params);LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(20),dp(20),dp(20),dp(20));body.addView(text(title,22));card.addView(body);return body;}
 private MaterialButton button(String label){MaterialButton b=new MaterialButton(this);b.setText(label);b.setAllCaps(false);b.setCornerRadius(dp(28));return b;}
 private TextView text(String label,int size){TextView t=new TextView(this);t.setText(label);t.setTextSize(size);t.setTextColor(getColor(size>=17?R.color.on_surface:R.color.on_surface_variant));t.setPadding(0,dp(4),0,dp(10));return t;}
 private int dp(float n){return PersonalizationUi.dp(this,n);}
}
